GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """
    Greedy placement followed by local-search refinement (moves and swaps)
    that repeatedly reduces the maximum KVPR across GPUs.
    """
    if not models:
        return {gpu_id: [] for gpu_id in range(gpu_num)}

    def kvprs(load, free):
        return [load[i] / free[i] if free[i] > 0 else float('inf') for i in range(len(load))]

    def greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            best, best_r = None, float('inf')
            for g in range(gpu_num):
                if model.model_size <= free[g]:
                    r = load[g] / free[g]
                    if r < best_r:
                        best_r, best = r, g
            if best is None:
                return None, None, None
            placement[best].append(model)
            load[best] += model.req_rate / model.slo
            free[best] -= model.model_size
        return placement, load, free

    # Lower-bound-guided construction: target the analytic LP bound
    # L = (sum req_rate/slo) / (gpus * MEM - sum sizes), assigning each model
    # to the GPU whose post-placement KVPR lands closest to L (equalizing
    # per-GPU pressure toward the analytic optimum) instead of greedily
    # minimizing each step. Falls back to incumbent greedy when infeasible.
    total_load = sum(m.req_rate / m.slo for m in models)
    total_free = gpu_num * GPU_MEM_SIZE - sum(m.model_size for m in models)
    L = total_load / total_free if total_free > 0 else float('inf')

    def target_greedy(order):
        placement = {g: [] for g in range(gpu_num)}
        free = [float(GPU_MEM_SIZE)] * gpu_num
        load = [0.0] * gpu_num
        for model in order:
            w = model.req_rate / model.slo
            best, best_key = None, None
            for g in range(gpu_num):
                denom = free[g] - model.model_size
                if denom <= 1e-12:
                    continue
                post = (load[g] + w) / denom
                # Prefer landing at or below the LP bound L; penalize overshoot.
                key = (post > L, abs(post - L), -free[g])
                if best_key is None or key < best_key:
                    best_key, best = key, g
            if best is None:
                return None, None, None
            placement[best].append(model)
            load[best] += w
            free[best] -= model.model_size
        return placement, load, free

    # Try target-greedy for a few orderings, keeping the best of
    # target-greedy AND plain greedy per ordering (target-greedy equalizes
    # toward the LP bound, but plain greedy can win on tight instances).
    best = None
    for order in (
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: m.req_rate / m.slo / m.model_size, reverse=True),
    ):
        for p, l, f in (target_greedy(order), greedy(order)):
            if p is not None and (best is None or max(kvprs(l, f)) < best[1]):
                best = (p, max(kvprs(l, f)), l, f)
    if best is None:
        raise ValueError("Unable to place models on any GPU within memory limits.")
    placement, cur_max, load, free = best

    # Population-based evolutionary search over assignment vectors, seeded by
    # the greedy/target-greedy constructions. Each generation: tournament
    # selection, set-partition crossover (per-GPU model subsets from one
    # parent, duplicates reassigned least-loaded with first-fit repair),
    # objective-directed mutation (move a model off the max-KVPR GPU to the
    # GPU minimizing resulting max KVPR), elitist retention. Fixed seed.
    import numpy as np
    rng = np.random.default_rng(0)
    sizes = [m.model_size for m in models]
    weights = [m.req_rate / m.slo for m in models]
    n = len(models)
    if gpu_num == 1:
        return {0: list(models)}

    def objective(assign):
        lo = [0.0] * gpu_num
        used = [0.0] * gpu_num
        for i, g in enumerate(assign):
            lo[g] += weights[i]
            used[g] += sizes[i]
        return max(lo[g] / (GPU_MEM_SIZE - used[g]) if used[g] < GPU_MEM_SIZE else float('inf')
                   for g in range(gpu_num))

    def feasible(assign):
        used = [0.0] * gpu_num
        for i, g in enumerate(assign):
            used[g] += sizes[i]
        return all(u <= GPU_MEM_SIZE for u in used)

    def repair(assign):
        """First-fit repair of overflowing GPUs; returns None if impossible."""
        assign = list(assign)
        used = [0.0] * gpu_num
        for i, g in enumerate(assign):
            used[g] += sizes[i]
        # Remove models from overflowing GPUs (keep list per GPU), then re-add.
        per_gpu = [[] for _ in range(gpu_num)]
        for i, g in enumerate(assign):
            per_gpu[g].append(i)
        new_assign = [-1] * n
        used = [0.0] * gpu_num
        for g in range(gpu_num):
            if sizes and used[g] <= GPU_MEM_SIZE:
                cap = 0.0
                keep = []
                for i in per_gpu[g]:
                    if cap + sizes[i] <= GPU_MEM_SIZE:
                        keep.append(i)
                        cap += sizes[i]
                # leave remainder models unassigned
                for i in keep:
                    new_assign[i] = g
                    used[g] += sizes[i]
        for i in range(n):
            if new_assign[i] == -1:
                cands = [g for g in range(gpu_num)
                         if used[g] + sizes[i] <= GPU_MEM_SIZE]
                if not cands:
                    return None
                g = min(cands, key=lambda gg: used[gg] + sizes[i])
                new_assign[i] = g
                used[g] += sizes[i]
        return new_assign

    def crossover(p1, p2):
        """Set-partition crossover: per-GPU subsets from p1 (else p2)."""
        child = [-1] * n
        used = [0.0] * gpu_num
        for g in range(gpu_num):
            if rng.random() < 0.5:
                src = p1
            else:
                src = p2
            members = [i for i in range(n) if src[i] == g]
            for i in members:
                if used[g] + sizes[i] <= GPU_MEM_SIZE:
                    child[i] = g
                    used[g] += sizes[i]
        ok = True
        for i in range(n):
            if child[i] == -1:
                cands = [gg for gg in range(gpu_num)
                         if used[gg] + sizes[i] <= GPU_MEM_SIZE]
                if not cands:
                    ok = False
                    break
                g = min(cands, key=lambda gg: used[gg])
                child[i] = g
                used[g] += sizes[i]
        return child if ok else None

    def mutate(assign):
        """Move a random model from the max-KVPR GPU to the best feasible GPU."""
        lo = [0.0] * gpu_num
        used = [0.0] * gpu_num
        for i, g in enumerate(assign):
            lo[g] += weights[i]
            used[g] += sizes[i]
        kv = [lo[g] / (GPU_MEM_SIZE - used[g]) for g in range(gpu_num)]
        gmax = max(range(gpu_num), key=lambda g: kv[g])
        movers = [i for i in range(n) if assign[i] == gmax]
        if not movers:
            movers = list(range(n))
        i = movers[int(rng.integers(len(movers)))]
        cand = list(assign)
        best_g, best_v = None, float('inf')
        for g in range(gpu_num):
            if g == gmax or used[g] + sizes[i] > GPU_MEM_SIZE:
                continue
            trial = list(cand)
            trial[i] = g
            v = objective(trial)
            if v < best_v:
                best_v, best_g = v, g
        if best_g is None:
            return None
        cand[i] = best_g
        return cand

    # Seed population from the incumbent placement plus random perturbations.
    x0 = [0] * n
    for g in range(gpu_num):
        for m in placement[g]:
            x0[models.index(m)] = g
    seeds = [x0]
    rng_arr = np.random.default_rng(1)
    while len(seeds) < 24:
        s = list(x0)
        for _ in range(int(rng_arr.integers(1, max(2, n // 2 + 1)))):
            i = int(rng_arr.integers(n))
            s[i] = int(rng_arr.integers(gpu_num))
        r = repair(s)
        if r is not None:
            seeds.append(r)
    pop = seeds
    fitness = [objective(a) for a in pop]
    best_idx = min(range(len(pop)), key=lambda k: fitness[k])
    best_x, best = pop[best_idx][:], fitness[best_idx]

    gens = 300
    for _ in range(gens):
        order = np.argsort(fitness)
        elite = pop[int(order[0])][:]
        elite_f = fitness[int(order[0])]
        new_pop, new_fit = [elite], [elite_f]
        while len(new_pop) < 24:
            # tournament selection
            def tourney():
                i, j = int(rng.integers(len(pop))), int(rng.integers(len(pop)))
                return pop[i] if fitness[i] <= fitness[j] else pop[j]
            p1, p2 = tourney(), tourney()
            if rng.random() < 0.5:
                child = crossover(p1, p2)
                if child is None:
                    child = list(p1)
            else:
                child = list(p1)
            if rng.random() < 0.7:
                mc = mutate(child)
                if mc is not None:
                    child = mc
            if not feasible(child):
                child = repair(child)
                if child is None:
                    child = list(p1)
            v = objective(child)
            new_pop.append(child)
            new_fit.append(v)
        pop, fitness = new_pop, new_fit
        bi = min(range(len(pop)), key=lambda k: fitness[k])
        if fitness[bi] < best:
            best_x, best = pop[bi][:], fitness[bi]

    placement = {g: [] for g in range(gpu_num)}
    for i, g in enumerate(best_x):
        placement[g].append(models[i])
    return placement

# EVOLVE-BLOCK-END


